import { Box, IconButton, Tooltip } from '@mui/material'
import Fullscreen from 'mdi-material-ui/Fullscreen'
import FullscreenExit from 'mdi-material-ui/FullscreenExit'
import type { CardTypeConfig } from '../../data/data_types'
import { MarkdownFormatToolbarControls } from '../editor/markdown_format_toolbar_controls'
import { CardPropertiesControl } from '../text_view/card_properties_control'

interface CardPopupToolbarControlsProps {
    cardTypes: CardTypeConfig[]
    isFullscreen: boolean
    isMobile: boolean
    onToggleFullscreen: () => void
    statusColors: Map<string, string>
}

/** Formatting controls arranged for the card details popup. */
export function CardPopupToolbarControls(props: CardPopupToolbarControlsProps) {
    const { cardTypes, isFullscreen, isMobile, onToggleFullscreen, statusColors } = props
    const label = isFullscreen ? 'Exit fullscreen' : 'Fullscreen'

    return (
        <MarkdownFormatToolbarControls endControls={(
            <>
                <Box sx={{ flex: 1 }} />
                <CardPropertiesControl binding="board-card" cardTypes={cardTypes} statusColors={statusColors} />
                {!isMobile ? (
                    <Tooltip title={label}>
                        <IconButton aria-label={label} onClick={onToggleFullscreen} size="small" sx={{ height: 30, width: 30 }}>
                            {isFullscreen ? <FullscreenExit sx={{ fontSize: 17 }} /> : <Fullscreen sx={{ fontSize: 17 }} />}
                        </IconButton>
                    </Tooltip>
                ) : null}
            </>
        )} />
    )
}

    visible: boolean
}

/** Card details editor anchored to the card that opened it. */
export function CardBodyPopover(props: CardBodyPopoverProps) {
    const {
        cardTypes,
        isMobile,
        onDeleteCard,
        onOpenAffects,
        onOpenInFileMode,
        statusColors,
        visible,
    } = props
    const { anchorElement, cardPath } = useSyncExternalStore(
        subscribeCardBodyPopover,
        () => cardBodyPopoverService.getSnapshot(),
        () => cardBodyPopoverService.getSnapshot(),
    )
    const card = useCardMetadata(cardPath)
    const activity = useCardConversations(cardPath)
    const [deleteCardPath, setDeleteCardPath] = useState<string | null>(null)
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const cardIdentity = card?.header.internalId
    const boardDocument = useBoardDocument(card?.path ?? null, cardIdentity, visible)
    const [isFullscreen, setIsFullscreen] = useState(false)
    const [popupContentElement, setPopupContentElement] = useState<HTMLDivElement | null>(null)
    const [selectedCardCommit, setSelectedCardCommit] = useState<SelectedCardCommit | null>(null)
    const [titleEdit, setTitleEdit] = useState<TitleEdit>({ path: null, title: '' })
    const titleDraft = titleEdit.path === card?.path ? titleEdit.title : card?.header.title ?? ''
    const cardCommits = useCardCommits(visible ? card?.header.internalId ?? null : null)
    const selectedCommit = visible && selectedCardCommit && selectedCardCommit.cardInternalId === card?.header.internalId
        ? selectedCardCommit.commit
        : null
    const missingCardIdentityError = visible && card && !cardIdentity
        ? new Error(`Card identity was not added before opening: ${card.path}`)
        : null
    useDialogError(missingCardIdentityError, 'Card details could not be opened')

    useEffect(() => {
        if (!visible || !cardPath) {
            cardMarkdownDataSource.setBoardDocument(null)
            historyStore.clear()
            return
        }
        if (!cardIdentity) return
        const currentCard = getProjectCard(cardPath)
        if (!currentCard) return

        const document = openFilesService.openBoardDocument(currentCard)
        cardMarkdownDataSource.setBoardDocument(document)

        return () => {
            cardMarkdownDataSource.setBoardDocument(null)
            historyStore.discardDocument(document)
            openFilesService.closeBoardDocument(document)
        }
    }, [cardIdentity, cardPath, historyStore, visible])

    useEffect(() => () => {
        cardMarkdownDataSource.setBoardDocument(null)
        historyStore.clear()
    }, [historyStore])

    const closePopover = () => {
        cardMarkdownDataSource.setBoardDocument(null)
        historyStore.clear()
        setIsFullscreen(false)
        setSelectedCardCommit(null)
        setTitleEdit({ path: null, title: '' })
        cardBodyPopoverService.close()
    }

    const handlePopoverClose = (reason?: 'backdropClick' | 'escapeKeyDown') => {
        if (reason === 'escapeKeyDown' && selectedCommit) {
            setSelectedCardCommit(null)
            return
        }
        closePopover()
    }

    const selectCommit = (commit: CardCommit) => {
        try {
            if (!card?.header.internalId) throw new Error('Cannot select card commit without an internal ID')
            setSelectedCardCommit({ cardInternalId: card.header.internalId, commit })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card commit could not be selected' })
        }
    }
    const clearSelectedCommit = () => setSelectedCardCommit(null)

    const openInFileMode = () => {
        if (!card) return
        setIsFullscreen(false)
        onOpenInFileMode(card.path)
    }

    const closeDeleteCardDialog = () => {
        setDeleteCardPath(null)
    }

    const openDeleteCardDialog = () => {
        if (!card) return
        setDeleteCardPath(card.path)
    }

    const openAffects = () => {
        if (card) onOpenAffects(card.path)
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
import { Box, MenuItem, MenuList, Typography } from '@mui/material'
import type { MouseEvent } from 'react'
import type { StateConfig } from '../../data/data_types'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import { useCardViewColumns } from './use_card_view_columns'
import { useMobileCardViewColumn } from './use_mobile_card_view_column'

interface MobileCardViewMenuProps {
    onSelected: () => void
    states: StateConfig[]
}

/** Visible board-column choices for mobile hamburger drawer. */
export function MobileCardViewMenu(props: MobileCardViewMenuProps) {
    const { onSelected, states } = props
    const columns = useCardViewColumns(states)
    const selectedColumn = useMobileCardViewColumn(columns)

    const handleSelectColumn = (event: MouseEvent<HTMLLIElement>) => {
        const status = event.currentTarget.dataset.status
        if (status === undefined) throw new Error('Missing mobile card column status')

        mobileCardViewService.selectColumn(status)
        onSelected()
    }

    return (
        <Box aria-label="Board columns">
            <Typography sx={{ color: 'text.secondary', fontWeight: 600, px: 2, pb: 0.5, pt: 1.5 }} variant="body2">
                Board columns
            </Typography>
            <MenuList>
                {columns.map(({ color, status }) => (
                    <MenuItem
                        data-status={status}
                        key={status}
                        onClick={handleSelectColumn}
                        selected={selectedColumn?.status === status}
                    >
                        <Box sx={{ bgcolor: color, borderRadius: '3px', height: 8, mr: 1, width: 8 }} />
                        {status || 'Unassigned'}
                    </MenuItem>
                ))}
            </MenuList>
        </Box>
    )
}

import { register } from '../service_injector'

export interface MobileCardViewSnapshot {
    selectedColumnStatus: string | null
}

const INITIAL_SNAPSHOT: MobileCardViewSnapshot = { selectedColumnStatus: null }

/** Owns selected column for mobile board and hamburger navigation. */
export class MobileCardViewService extends EventTarget {
    private snapshot = INITIAL_SNAPSHOT

    getSnapshot(): MobileCardViewSnapshot {
        return this.snapshot
    }

    selectColumn(status: string) {
        this.update({ selectedColumnStatus: status })
    }

    selectVisibleColumn(visibleStatuses: string[]) {
        const { selectedColumnStatus } = this.snapshot
        const nextStatus = selectedColumnStatus !== null && visibleStatuses.includes(selectedColumnStatus)
            ? selectedColumnStatus
            : visibleStatuses[0] ?? null
        this.update({ selectedColumnStatus: nextStatus })
    }

    private update(snapshot: MobileCardViewSnapshot) {
        if (snapshot.selectedColumnStatus === this.snapshot.selectedColumnStatus) return

        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<MobileCardViewSnapshot>('changed', { detail: snapshot }))
    }
}

export const mobileCardViewService = register('mobileCardViewService', new MobileCardViewService())

import { useEffect, useSyncExternalStore } from 'react'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import type { VisibleCardColumn } from './use_card_view_columns'

function subscribe(listener: () => void) {
    mobileCardViewService.addEventListener('changed', listener)

    return () => mobileCardViewService.removeEventListener('changed', listener)
}

function getSnapshot() {
    return mobileCardViewService.getSnapshot().selectedColumnStatus
}

/** Returns selected visible mobile column and repairs missing or hidden selections. */
export function useMobileCardViewColumn(columns: VisibleCardColumn[]) {
    const selectedStatus = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const selectedColumn = columns.find(({ status }) => status === selectedStatus) ?? columns[0] ?? null

    useEffect(() => {
        mobileCardViewService.selectVisibleColumn(columns.map(({ status }) => status))
    }, [columns])

    return selectedColumn
}

