import { Box, MenuItem, MenuList, Typography } from '@mui/material'
import type { MouseEvent } from 'react'
import type { StateConfig } from '../../data/data_types'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import { useCardViewColumns } from './use_card_view_columns'
import { useMobileCardViewColumn } from './use_mobile_card_view_column'

interface MobileCardViewMenuProps {
    onSelected: () => void
    states: StateConfig[]
}

/** Visible board-column choices for mobile hamburger drawer. */
export function MobileCardViewMenu(props: MobileCardViewMenuProps) {
    const { onSelected, states } = props
    const columns = useCardViewColumns(states)
    const selectedColumn = useMobileCardViewColumn(columns)

    const handleSelectColumn = (event: MouseEvent<HTMLLIElement>) => {
        const status = event.currentTarget.dataset.status
        if (status === undefined) throw new Error('Missing mobile card column status')

        mobileCardViewService.selectColumn(status)
        onSelected()
    }

    return (
        <Box aria-label="Board columns">
            <Typography sx={{ color: 'text.secondary', fontWeight: 600, px: 2, pb: 0.5, pt: 1.5 }} variant="body2">
                Board columns
            </Typography>
            <MenuList>
                {columns.map(({ color, status }) => (
                    <MenuItem
                        data-status={status}
                        key={status}
                        onClick={handleSelectColumn}
                        selected={selectedColumn?.status === status}
                    >
                        <Box sx={{ bgcolor: color, borderRadius: '3px', height: 8, mr: 1, width: 8 }} />
                        {status || 'Unassigned'}
                    </MenuItem>
                ))}
            </MenuList>
        </Box>
    )
}

import { register } from '../service_injector'

export interface MobileCardViewSnapshot {
    selectedColumnStatus: string | null
}

const INITIAL_SNAPSHOT: MobileCardViewSnapshot = { selectedColumnStatus: null }

/** Owns selected column for mobile board and hamburger navigation. */
export class MobileCardViewService extends EventTarget {
    private snapshot = INITIAL_SNAPSHOT

    getSnapshot(): MobileCardViewSnapshot {
        return this.snapshot
    }

    selectColumn(status: string) {
        this.update({ selectedColumnStatus: status })
    }

    selectVisibleColumn(visibleStatuses: string[]) {
        const { selectedColumnStatus } = this.snapshot
        const nextStatus = selectedColumnStatus !== null && visibleStatuses.includes(selectedColumnStatus)
            ? selectedColumnStatus
            : visibleStatuses[0] ?? null
        this.update({ selectedColumnStatus: nextStatus })
    }

    private update(snapshot: MobileCardViewSnapshot) {
        if (snapshot.selectedColumnStatus === this.snapshot.selectedColumnStatus) return

        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<MobileCardViewSnapshot>('changed', { detail: snapshot }))
    }
}

export const mobileCardViewService = register('mobileCardViewService', new MobileCardViewService())

import { useEffect, useSyncExternalStore } from 'react'
import { mobileCardViewService } from '../../services/project/mobile_card_view_service'
import type { VisibleCardColumn } from './use_card_view_columns'

function subscribe(listener: () => void) {
    mobileCardViewService.addEventListener('changed', listener)

    return () => mobileCardViewService.removeEventListener('changed', listener)
}

function getSnapshot() {
    return mobileCardViewService.getSnapshot().selectedColumnStatus
}

/** Returns selected visible mobile column and repairs missing or hidden selections. */
export function useMobileCardViewColumn(columns: VisibleCardColumn[]) {
    const selectedStatus = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
    const selectedColumn = columns.find(({ status }) => status === selectedStatus) ?? columns[0] ?? null

    useEffect(() => {
        mobileCardViewService.selectVisibleColumn(columns.map(({ status }) => status))
    }, [columns])

    return selectedColumn
}

